INSERT INTO t_prd_product_constraints (prd_cd,rule_cd,rule_nm,rule_typ_cd,logic,err_msg,use_yn,del_yn,reg_dt) VALUES ('PRD_000049','R_EXCL_COATING_THIN_PAPER','[제약조건] 코팅은 두꺼운 종이(180g 이상)에서만 가능','RULE_TYPE.02','{"!":{"and":[{"or":[{"in":["OPV_000613",{"var":"sel_opts"}]},{"in":["OPV_000614",{"var":"sel_opts"}]}]},{"or":[{"===":[{"var":"mat_cd__usage_cd"},"MAT_000083__USAGE.07"]},{"===":[{"var":"mat_cd__usage_cd"},"MAT_000110__USAGE.07"]}]}]}}'::jsonb,'코팅은 두꺼운 종이(180g 이상)에서만 가능합니다. 종이를 180g 이상으로 바꾸거나 코팅을 빼 주세요.','Y','N',now()) ON CONFLICT (prd_cd,rule_cd) DO UPDATE SET rule_nm=EXCLUDED.rule_nm,rule_typ_cd=EXCLUDED.rule_typ_cd,logic=EXCLUDED.logic,err_msg=EXCLUDED.err_msg,use_yn='Y',del_yn='N',upd_dt=now();
